import { buildAttributionReminder, type AttributionConfig } from '@alran/config';

const MAX_REMEMBERED_SESSIONS = 256;

/**
 * The attribution system reminder: how Alran Code asks the model to sign its commits and pull requests
 * (`Co-Authored-By: Alran Code using <model> <noreply@alran.dev>`, `Generated by [Alran Code](...)`).
 * The text is `buildAttributionReminder` in `@alran/config`; this decides when it is worth sending.
 *
 * The reminder goes into the model's context once: on the first turn of a session, again after a
 * compaction dropped it, and again when the turn runs on another model (the commit line names it). Every
 * other turn gets nothing, so it costs a few tokens per session, not per message. A commit still carries
 * its trailer when the reminder was missed: the host adds it to `git commit` itself (see
 * `ensure-git-shim.ts` in local-runtime).
 */
export interface AttributionReminderSource {
  /**
   * The text for this turn (without the `<system-reminder>` tags), or `''` when there is nothing to
   * say: the user switched both lines off, or the model already has this exact text.
   */
  readonly build: (input: {
    readonly sessionId: string;
    readonly agentConfig: Readonly<Record<string, unknown>>;
    /** True when the model-visible history since the last compaction already carries this session's context. */
    readonly sessionIdInContext?: boolean;
  }) => string;
}

export function createAttributionReminder(options: {
  readonly readConfig: () => { readonly attribution?: Partial<AttributionConfig> } | undefined;
}): AttributionReminderSource {
  const announced = new Map<string, string>();
  return {
    build: ({ sessionId, agentConfig, sessionIdInContext }) => {
      const model = readRecord(agentConfig.model);
      const text = buildAttributionReminder({
        model: typeof model?.model_id === 'string' ? { model_id: model.model_id } : undefined,
        config: options.readConfig()?.attribution,
      });
      if (!text) {
        announced.delete(sessionId);
        return '';
      }
      if (announced.get(sessionId) === text && sessionIdInContext === true) return '';
      announced.delete(sessionId);
      announced.set(sessionId, text);
      if (announced.size > MAX_REMEMBERED_SESSIONS) {
        const oldest = announced.keys().next().value;
        if (oldest !== undefined) announced.delete(oldest);
      }
      return text;
    },
  };
}

function readRecord(value: unknown): Readonly<Record<string, unknown>> | undefined {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? (value as Readonly<Record<string, unknown>>)
    : undefined;
}
